/* ---- server ---------------------------------------------------------- */

/* Handlers: return OK and fill the results, or an ERR_* for the client.
 * A NULL handler answers ERR_NOT_SUPPORTED. */
struct usb_ops {
    status_t (*info)(void *ctx, uint16_t *out_vendor, uint16_t *out_product, uint8_t *out_speed, uint8_t *out_interface_number, uint8_t *out_class_code, uint8_t *out_subclass, uint8_t *out_protocol, uint8_t *out_num_endpoints, uint8_t *out_alt_setting, uint8_t *out_address);
    status_t (*get_descriptor)(void *ctx, uint8_t type, uint8_t index, uint16_t lang, uint16_t length, uint8_t interface_recipient, uint16_t *out_actual, uint8_t out_data[1024]);
    status_t (*control_in)(void *ctx, uint8_t request_type, uint8_t request, uint16_t value, uint16_t index, uint16_t length, uint16_t *out_actual, uint8_t out_data[1024]);
    status_t (*control_out)(void *ctx, uint8_t request_type, uint8_t request, uint16_t value, uint16_t index, uint16_t length, const uint8_t data[64]);
    status_t (*open_interrupt_in)(void *ctx, uint8_t endpoint, handle_t *out_reports, uint16_t *out_max_packet, uint8_t *out_interval_ms);
    status_t (*endpoint_stats)(void *ctx, uint8_t endpoint, uint64_t *out_reports, uint64_t *out_dropped, uint64_t *out_errors, uint8_t *out_open);
    status_t (*set_interface)(void *ctx, uint8_t alt_setting);
    status_t (*open_bulk)(void *ctx, uint8_t ep_in, uint8_t ep_out, handle_t *out_buffer, uint32_t *out_size);
    status_t (*bulk_in)(void *ctx, uint32_t offset, uint32_t length, uint32_t timeout_ms, uint32_t *out_actual);
    status_t (*bulk_out)(void *ctx, uint32_t offset, uint32_t length, uint32_t timeout_ms, uint32_t *out_actual);
    status_t (*clear_halt)(void *ctx, uint8_t endpoint);
};

/* Decode the request of n bytes at req, call its handler, encode the reply
 * into rep (USB_REP_MAX bytes) and the handles it carries into rhs
 * (IDL_REP_HANDLES slots; *rhn of them). Returns the reply's length: 0
 * means no reply (the request has no txid). No I/O; the caller sends the
 * reply with the handles, or closes them if it can't. */
static inline uint32_t usb_dispatch(const struct usb_ops *ops, void *ctx, const void *req, uint32_t n,
                                    void *rep, handle_t *rhs, uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    if (n < sizeof(uint32_t))
        return 0;
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    if (n < sizeof(struct idl_req_hdr))
        return sizeof(*idl_h);
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case USB_INFO: {
        const struct usb_info_req *idl_q = (const struct usb_info_req *)req;
        struct usb_info_rep *idl_r = (struct usb_info_rep *)rep;
        uint16_t out_vendor = 0;
        uint16_t out_product = 0;
        uint8_t out_speed = 0;
        uint8_t out_interface_number = 0;
        uint8_t out_class_code = 0;
        uint8_t out_subclass = 0;
        uint8_t out_protocol = 0;
        uint8_t out_num_endpoints = 0;
        uint8_t out_alt_setting = 0;
        uint8_t out_address = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->info) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->info(ctx, &out_vendor, &out_product, &out_speed, &out_interface_number, &out_class_code, &out_subclass, &out_protocol, &out_num_endpoints, &out_alt_setting, &out_address);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->vendor = out_vendor;
        idl_r->product = out_product;
        idl_r->speed = out_speed;
        idl_r->interface_number = out_interface_number;
        idl_r->class_code = out_class_code;
        idl_r->subclass = out_subclass;
        idl_r->protocol = out_protocol;
        idl_r->num_endpoints = out_num_endpoints;
        idl_r->alt_setting = out_alt_setting;
        idl_r->address = out_address;
        return sizeof(*idl_r);
    }
    case USB_GET_DESCRIPTOR: {
        const struct usb_get_descriptor_req *idl_q = (const struct usb_get_descriptor_req *)req;
        struct usb_get_descriptor_rep *idl_r = (struct usb_get_descriptor_rep *)rep;
        uint16_t out_actual = 0;
        uint8_t out_data[1024];
        for (uint32_t idl_i = 0; idl_i < 1024; idl_i++)
            out_data[idl_i] = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->get_descriptor) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->get_descriptor(ctx, idl_q->type, idl_q->index, idl_q->lang, idl_q->length, idl_q->interface_recipient, &out_actual, out_data);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->actual = out_actual;
        for (uint32_t idl_i = 0; idl_i < 1024; idl_i++)
            idl_r->data[idl_i] = out_data[idl_i];
        return sizeof(*idl_r);
    }
    case USB_CONTROL_IN: {
        const struct usb_control_in_req *idl_q = (const struct usb_control_in_req *)req;
        struct usb_control_in_rep *idl_r = (struct usb_control_in_rep *)rep;
        uint16_t out_actual = 0;
        uint8_t out_data[1024];
        for (uint32_t idl_i = 0; idl_i < 1024; idl_i++)
            out_data[idl_i] = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->control_in) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->control_in(ctx, idl_q->request_type, idl_q->request, idl_q->value, idl_q->index, idl_q->length, &out_actual, out_data);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->actual = out_actual;
        for (uint32_t idl_i = 0; idl_i < 1024; idl_i++)
            idl_r->data[idl_i] = out_data[idl_i];
        return sizeof(*idl_r);
    }
    case USB_CONTROL_OUT: {
        const struct usb_control_out_req *idl_q = (const struct usb_control_out_req *)req;
        struct usb_control_out_rep *idl_r = (struct usb_control_out_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->control_out) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->control_out(ctx, idl_q->request_type, idl_q->request, idl_q->value, idl_q->index, idl_q->length, idl_q->data);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case USB_OPEN_INTERRUPT_IN: {
        const struct usb_open_interrupt_in_req *idl_q = (const struct usb_open_interrupt_in_req *)req;
        struct usb_open_interrupt_in_rep *idl_r = (struct usb_open_interrupt_in_rep *)rep;
        handle_t out_reports = HANDLE_INVALID;
        uint16_t out_max_packet = 0;
        uint8_t out_interval_ms = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->open_interrupt_in) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->open_interrupt_in(ctx, idl_q->endpoint, &out_reports, &out_max_packet, &out_interval_ms);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_reports != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_reports != HANDLE_INVALID)
                drv_handle_close(out_reports);
            return sizeof(*idl_h);
        }
        rhs[0] = out_reports;
        *rhn = 1;
        idl_r->max_packet = out_max_packet;
        idl_r->interval_ms = out_interval_ms;
        return sizeof(*idl_r);
    }
    case USB_ENDPOINT_STATS: {
        const struct usb_endpoint_stats_req *idl_q = (const struct usb_endpoint_stats_req *)req;
        struct usb_endpoint_stats_rep *idl_r = (struct usb_endpoint_stats_rep *)rep;
        uint64_t out_reports = 0;
        uint64_t out_dropped = 0;
        uint64_t out_errors = 0;
        uint8_t out_open = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->endpoint_stats) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->endpoint_stats(ctx, idl_q->endpoint, &out_reports, &out_dropped, &out_errors, &out_open);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->reports = out_reports;
        idl_r->dropped = out_dropped;
        idl_r->errors = out_errors;
        idl_r->open = out_open;
        return sizeof(*idl_r);
    }
    case USB_SET_INTERFACE: {
        const struct usb_set_interface_req *idl_q = (const struct usb_set_interface_req *)req;
        struct usb_set_interface_rep *idl_r = (struct usb_set_interface_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->set_interface) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->set_interface(ctx, idl_q->alt_setting);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case USB_OPEN_BULK: {
        const struct usb_open_bulk_req *idl_q = (const struct usb_open_bulk_req *)req;
        struct usb_open_bulk_rep *idl_r = (struct usb_open_bulk_rep *)rep;
        handle_t out_buffer = HANDLE_INVALID;
        uint32_t out_size = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->open_bulk) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->open_bulk(ctx, idl_q->ep_in, idl_q->ep_out, &out_buffer, &out_size);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_buffer != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_buffer != HANDLE_INVALID)
                drv_handle_close(out_buffer);
            return sizeof(*idl_h);
        }
        rhs[0] = out_buffer;
        *rhn = 1;
        idl_r->size = out_size;
        return sizeof(*idl_r);
    }
    case USB_BULK_IN: {
        const struct usb_bulk_in_req *idl_q = (const struct usb_bulk_in_req *)req;
        struct usb_bulk_in_rep *idl_r = (struct usb_bulk_in_rep *)rep;
        uint32_t out_actual = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->bulk_in) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->bulk_in(ctx, idl_q->offset, idl_q->length, idl_q->timeout_ms, &out_actual);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->actual = out_actual;
        return sizeof(*idl_r);
    }
    case USB_BULK_OUT: {
        const struct usb_bulk_out_req *idl_q = (const struct usb_bulk_out_req *)req;
        struct usb_bulk_out_rep *idl_r = (struct usb_bulk_out_rep *)rep;
        uint32_t out_actual = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->bulk_out) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->bulk_out(ctx, idl_q->offset, idl_q->length, idl_q->timeout_ms, &out_actual);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->actual = out_actual;
        return sizeof(*idl_r);
    }
    case USB_CLEAR_HALT: {
        const struct usb_clear_halt_req *idl_q = (const struct usb_clear_halt_req *)req;
        struct usb_clear_halt_rep *idl_r = (struct usb_clear_halt_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->clear_halt) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->clear_halt(ctx, idl_q->endpoint);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    }
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* Take one message off ch and answer it. OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t usb_serve_one(handle_t ch, const struct usb_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[USB_REQ_MAX];
    _Alignas(8) uint8_t idl_r[USB_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, sizeof(idl_q), &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL)
        return idl_drain(ch, idl_n, idl_nh);
    if (idl_st != OK)
        return idl_st;
    if (idl_nh) {
        idl_close_all(idl_hs, idl_nh);
        idl_reply_status(ch, idl_q, idl_n, ERR_INVALID_ARGS);
        return OK;
    }
    handle_t idl_rhs[IDL_REP_HANDLES];
    uint32_t idl_rhn = 0;
    uint32_t idl_rn = usb_dispatch(ops, ctx, idl_q, idl_n, idl_r, idl_rhs, &idl_rhn);
    if (!idl_rn || drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn) != OK)
        idl_close_all(idl_rhs, idl_rhn);   /* not sent: they're still ours */
    return OK;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). */
static inline status_t usb_serve(handle_t ch, const struct usb_ops *ops, void *ctx)
{
    for (;;) {
        status_t idl_st = usb_serve_one(ch, ops, ctx);
        if (idl_st == OK)
            continue;
        if (idl_st == ERR_PEER_CLOSED)
            return OK;
        if (idl_st != ERR_SHOULD_WAIT)
            return idl_st;
        signals_t idl_seen = 0;
        idl_st = drv_object_wait_one(ch, SIG_READABLE | SIG_PEER_CLOSED, DEADLINE_NEVER,
                                     &idl_seen);
        if (idl_st != OK)
            return idl_st;
    }
}
